package com.arenashowdown.lobby;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.scoreboard.*;import org.bukkit.util.Transformation;import org.joml.Vector3f;import java.util.*;
final class VisualManager{
 static final String TAG="arena_lobby_managed";private final ArenaLobbyPlugin plugin;private final Map<String,TextDisplay>holograms=new HashMap<>();private final Map<UUID,String>signatures=new HashMap<>();private final Map<UUID,Scoreboard>boards=new HashMap<>();
 VisualManager(ArenaLobbyPlugin p){plugin=p;}
 void rebuild(){removeHolograms();var s=plugin.getConfig().getConfigurationSection("holograms");if(s!=null)for(String id:s.getKeys(false)){Location at=plugin.location("holograms."+id);if(at!=null)spawn(id,s.getString(id+".type","ranking"),at);}}
 private void spawn(String id,String type,Location at){TextDisplay d=at.getWorld().spawn(at,TextDisplay.class,e->{e.addScoreboardTag(TAG);e.setPersistent(false);e.setBillboard(Display.Billboard.CENTER);e.setShadowed(true);e.setBackgroundColor(Color.fromARGB(170,8,8,8));e.setTransformation(new Transformation(new Vector3f(),e.getTransformation().getLeftRotation(),new Vector3f(1.1f),e.getTransformation().getRightRotation()));});holograms.put(id,d);updateOne(d,type);}
 void update(){var s=plugin.getConfig().getConfigurationSection("holograms");if(s!=null)holograms.forEach((id,d)->updateOne(d,s.getString(id+".type","ranking")));for(Player p:Bukkit.getOnlinePlayers())updatePlayer(p);}
 void updatePlayer(Player p){if(!plugin.isLobby(p.getWorld()))return;String signature=signature(p);if(signature.equals(signatures.get(p.getUniqueId())))return;signatures.put(p.getUniqueId(),signature);board(p);tab(p);}
 private String signature(Player p){var v=plugin.state().view;return v.name()+v.state()+v.round()+v.next()+v.ranking().toString()+v.team(p.getUniqueId())+p.hasPermission("arena.lobby.admin");}
 private void board(Player p){if(!plugin.getConfig().getBoolean("scoreboard.enabled",true))return;Scoreboard old=p.getScoreboard();if(old.getObjective("parkour")!=null)return;Scoreboard b=Bukkit.getScoreboardManager().getNewScoreboard();Objective o=b.registerNewObjective("arena_lobby",Criteria.DUMMY,plugin.text(plugin.getConfig().getString("scoreboard.title","&6&lARENA SHOWDOWN")));o.setDisplaySlot(DisplaySlot.SIDEBAR);var v=plugin.state().view;List<String>lines=new ArrayList<>();lines.add("&f"+v.name());if(v.totalRounds()>0)lines.add("&7Rodada: &e"+v.round()+"/"+v.totalRounds());lines.add("&8 ");if(!v.ranking().isEmpty()){lines.add("&6CLASSIFICACAO");int i=1;for(var r:v.ranking()){if(i>plugin.getConfig().getInt("scoreboard.entries",3))break;lines.add("&f"+i+++". "+r.playerName()+" &e"+r.points());}}lines.add("&8  ");lines.add("&6PROXIMO JOGO");lines.add("&f"+v.next());lines.add("&7arenashowdown");int score=lines.size();for(String line:lines)o.getScore(plugin.legacy(line)+"§"+Integer.toHexString(score%16)).setScore(score--);p.setScoreboard(b);boards.put(p.getUniqueId(),b);}
 private void tab(Player p){var v=plugin.state().view;p.sendPlayerListHeaderAndFooter(plugin.text(plugin.getConfig().getString("tab.header","&6&l✦ ARENA SHOWDOWN ✦\n&fCampeonato de Streamers\n&7Prepare-se para o proximo desafio!")),plugin.text(plugin.getConfig().getString("tab.footer","&eCampeonato: &f%championship%\n&eRodada: &f%round%/%total%\n&eProximo desafio: &f%next%\n&7Arena Showdown").replace("%championship%",v.name()).replace("%round%",String.valueOf(v.round())).replace("%total%",String.valueOf(v.totalRounds())).replace("%next%",v.next())));String team=v.team(p.getUniqueId());String prefix=p.hasPermission("arena.lobby.admin")?"&c[ADMIN] ":team.isBlank()?"&7[ESPECTADOR] ":"&6["+team+"] ";p.playerListName(plugin.text(prefix+"&f"+p.getName()));}
 private void updateOne(TextDisplay d,String type){if(!d.isValid())return;var v=plugin.state().view;String text=switch(type){case"championship"->"&6&l"+v.name()+"\n&fEstado: &e"+v.state()+"\n&fRodada: &e"+v.round()+"/"+v.totalRounds()+"\n&fProximo: &e"+v.next();case"last"->"&6&lULTIMA PARTIDA\n&7Consulte /arena status";default->{StringBuilder b=new StringBuilder("&6&lRANKING GERAL");int i=1;for(var r:v.ranking())b.append("\n&e").append(i++).append(". &f").append(r.playerName()).append(" &6").append(r.points());if(v.ranking().isEmpty())b.append("\n&7Sem pontuacao");yield b.toString();}};d.text(plugin.text(text));}
 void leave(Player p){signatures.remove(p.getUniqueId());boards.remove(p.getUniqueId());if(p.getScoreboard().getObjective("arena_lobby")!=null)p.setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());p.sendPlayerListHeaderAndFooter(net.kyori.adventure.text.Component.empty(),net.kyori.adventure.text.Component.empty());p.playerListName(null);}
 void invalidate(){signatures.clear();}
 void removeHolograms(){World w=plugin.world();if(w!=null)for(Entity e:w.getEntities())if(e.getScoreboardTags().contains(TAG))e.remove();holograms.clear();}
 void shutdown(){removeHolograms();for(Player p:Bukkit.getOnlinePlayers())leave(p);}
}
